-- migrations/036_map_themes.up.sql
-- Generated by `go run ./cmd/mapgen` from internal/game/mapgen: edit the layouts there and rerun it.

-- How the client draws a map (gamedata.MapThemes); maps without one keep today's look.
ALTER TABLE config_maps ADD COLUMN IF NOT EXISTS theme TEXT NOT NULL DEFAULT 'grassland';

-- Brick types of the generated maps: the admin seed's 5 defaults (1 Dirt = soft block, 2 Rock =
-- hard block) and the soft / hard slope, ceiling, half and plank shapes. Rows that exist are kept.
ON CONFLICT (brick_type_id) DO NOTHING;
SELECT setval(pg_get_serial_sequence('config_brick_types', 'brick_type_id'), (SELECT MAX(brick_type_id) FROM config_brick_types));

-- Vietnamese names (mapName) for the legacy maps, unless an admin renamed them
UPDATE config_maps SET name = 'Thung lũng cỏ' WHERE map_id = 'grassland_valley' AND name = 'Grassland Valley';
UPDATE config_maps SET name = 'Đỉnh băng' WHERE map_id = 'frozen_peak' AND name = 'Frozen Peak';
